// ==== Ojos amarillos de Pennywise: aparecen al SONREIR ====
// AJUSTES
var TAMANO = 1;                              // tamaño de los ojos
var SONIDO = "assets/sonidos/it_risa.mp3";   // pon aqui tu mp3 (opcional). Si no existe, suena una risa sintetizada.
var VOLUMEN = 1;
var on = false, k = 0;

function start() { this.visible = false; }

function smileStart() {
	on = true;
	// Solo un ojo dispara el sonido (si no sonaria doble).
	if (this.name === "ojo_izq" && window.folio) window.folio.sfx.fileOr(SONIDO, "itlaugh", VOLUMEN);
}
function smileEnd() { on = false; }

function update(event) {
	k += ((on ? 1 : 0) - k) * Math.min(1, event.delta / 110);
	this.visible = k > 0.02;
	var blink = (typeof face !== "undefined" && face) ? face.blink : 0;   // se cierran al parpadear
	this.scale.set(-k * TAMANO, Math.max(0.001, k * TAMANO * (1 - blink * 0.9)), 1);
}

